# Generated by Phase: IMPLEMENT | Feature: EVOL-043
"""Retired-vocabulary ratchet: a term a decision record retires stops being writable across the governed tree.

Config (`config/quality.json` → `retired_terms`): [{"term": "…", "record": "ADR-…", "exempt": [globs]}] —
`term` and `record` are mandatory (a retirement without its record is not a ratchet). Exemption classes,
always on (history is not rewritten): docs/project_log/**, the governance manifest, config/quality.json
itself, worklogs, hook state, changelogs (HISTORY_EXEMPT). Scan set = coherence-context.json
audit.root_sets minus audit.exclusions.
"""
from __future__ import annotations

import fnmatch
from pathlib import Path

from .common import GateFault, any_glob, glob_match, key, load_coherence, tracked_files

HISTORY_EXEMPT = ("docs/project_log/**", "**/governance_versions.json", "config/quality.json", "**/*.log.jsonl",
                  ".claude/state/**", "**/CHANGELOG*")


def _terms(repo: Path) -> list[dict]:
    terms = key(repo, "retired_terms", default=[]) or []
    for t in terms:
        if not isinstance(t, dict) or not t.get("term") or not t.get("record"):
            raise GateFault("config/quality.json retired_terms: every entry needs `term` and `record` (the decision that retired it)")
    return terms


def _in_scope(rel: str, roots: list[str], exclusions: list[str]) -> bool:
    if not any(r == "." or glob_match(rel, r.rstrip("/") + "/") for r in roots):
        return False
    if any(rel.startswith(x) or fnmatch.fnmatch(Path(rel).name, x) for x in exclusions):
        return False
    return not any_glob(rel, HISTORY_EXEMPT)


def scan(repo: Path) -> list[dict]:
    terms = _terms(repo)
    if not terms:
        return []
    audit = load_coherence(repo).get("audit", {})
    roots, exclusions = audit.get("root_sets") or ["."], audit.get("exclusions") or []
    hits: list[dict] = []
    for rel in tracked_files(repo):
        if not _in_scope(rel, roots, exclusions):
            continue
        try:
            lines = (repo / rel).read_text(encoding="utf-8", errors="replace").splitlines()
        except OSError:
            continue
        for t in terms:
            if any_glob(rel, t.get("exempt") or []):
                continue
            hits += [{"path": rel, "line": n, "term": t["term"], "record": t["record"]}
                     for n, line in enumerate(lines, 1) if t["term"] in line]
    return hits


def render(hits: list[dict]) -> str:
    if not hits:
        return "retired-terms: ok — no retired term written in the governed tree."
    out = [f"retired-terms: FAIL — {len(hits)} occurrence(s) of retired vocabulary:"]
    out += [f"  {h['path']}:{h['line']}: `{h['term']}` (retired by {h['record']})" for h in hits[:50]]
    if len(hits) > 50:
        out.append(f"  … {len(hits) - 50} more")
    out.append("A retired term is history, not law: rewrite the sentence, or declare an exemption glob on the term in config/quality.json.")
    return "\n".join(out)
